import type { DialogueEntry } from '../../../types';
import { CharacterId } from '../characters';
import { Portrait } from '../portraits';
import { Background } from '../backgrounds';

export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "三個月後。下午。家屬律師辦公室。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "窗簾拉了一半。百葉窗把下午的光切成一條一條，落在桌上的文件夾上。桌上有一台筆電，螢幕亮著。螢幕上是 Public Witness Index。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）三個月了。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）循環沒有回來。時間還在走。可是——三個月走下來，世界沒有變成一個乾淨的答案。世界變成——這個。一個還在吵的頁面。一疊還沒解封的文件。一個律師坐在對面，手邊放著兩個牛皮紙信封。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上。Public Witness Index。不是一條時間線。是一個分層的查驗介面。每一筆資料旁邊都有欄位。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "PROVENANCE——VERIFIED／UNVERIFIED。CONSENT——PATIENT／PROXY／PUBLIC／SEALED。DOCUMENT CORRELATION——YES／NO／PARTIAL。CONTENT TYPE——FACT／MEMORY／DREAM／IMPRESSION。OBJECTIVE CORROBORATION——LEVEL。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）分層。不是——所有東西排成一排。是——每一筆都被標了來源、同意、關聯、內容類型、客觀核實程度。你看得到的時候就知道——哪些是文件可以證明的。哪些是——有人記得但無法從外面驗證的。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕捲動。上半部。可高度核實的資料。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "姓名。失蹤日期。轉移紀錄。工單。ROLE DELEGATION。BUNDLE HASH。MOBILE PAYLOAD。COURT HOLD。每一筆旁邊——PROVENANCE VERIFIED。OBJECTIVE CORROBORATION HIGH。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）這些——是文件。是系統紀錄。是法院可以調的東西。姓名、日期、工單、hash——這些不取決於誰記得什麼。這些——是制度自己留下的痕跡。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕捲動。下半部。來源可核實，但內容主觀。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "黑色海。倒月。「七條不是路」。陌生熟悉感。時間錯位。每一筆旁邊——PROVENANCE VERIFIED。CONTENT TYPE——MEMORY／DREAM／IMPRESSION。OBJECTIVE CORROBORATION——LOW／NONE。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）來源是真的。有人真的寫下了這些。有人真的畫了黑色海。有人真的說了「七條不是路」。可是——內容。內容是——主觀的。是——只有經歷的人自己知道的。外面的人——可以看見這筆資料存在。看不見——它是不是客觀正確。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕右側。東京 public-health reports。三個月累積的事後報告。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "MASS CATASTROPHIC EVENT——NOT OBSERVED。ORDINARY SERVICES——OPERATING。TRANSIENT REPORTS——PRESENT／LIMITED。HOSPITAL SURGE——MODERATE／MANAGEABLE。LONG-TERM PUBLIC EFFECT——UNKNOWN。CAUSAL ATTRIBUTION——NOT ESTABLISHED。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）沒有群體災難。沒有——函館夜潮那種十七個人同時昏迷。可是——也不是什麼都沒有。有限短暫症狀。有人短暫看到黑色海。有人報告陌生熟悉感。有人失語幾秒鐘。有人時間錯位。有人——沒有任何異常。有人只收到中立的 availability notice，後來自己開啟了 fragments。有人——把白光感受和網路上看到的文件混為一談，說自己經歷了什麼其實只是讀到的。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）因果——仍爭議。有人說症狀是外星訊號造成的。有人說是保護性濾波不完全。有人說是集體心理暗示。有人說——只是那天早上本來就有很多人沒睡好。沒有——單一成因被證明。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕底部。媒體與公共爭議區。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "有媒體依文件持續追查。有媒體——獵奇化主觀 fragments，把黑色海和倒月做成標題。患者權利團體要求移除未成年敏感內容。Index 依撤回／更正程序調整可見性。第七曙光內部——對公開尺度保持分歧。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）沒有統一版本。三個月了。還是——沒有統一版本。有人追查。有人消費。有人要求保護未成年人。有人覺得公開不夠。有人覺得公開太多。Index 在中間——調整。撤回。更正。標注。不是——刪掉。也不是——全部攤開。是——一層一層地標清楚。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "律師把兩個牛皮紙信封推到桌面中間。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Lawyer, character: "律師", dialogue: "兩條獨立證據鏈。不來自同一個來源。不依賴同一個部門。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）兩個信封。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Lawyer, character: "律師", dialogue: "第一條。Independent medical transfer clearance。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他打開第一個信封。一張文件。上面是制式表格。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "SUBJECT HASH——<FATHER-HASH>。STATUS AT EXAM——ALIVE。BIOMETRIC／SIGN——MATCH。TRANSPORT FITNESS——CLEARED／RESTRICTED。DATE——OFFICIAL DISAPPEARANCE + 11 DAYS。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）alive。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）status at exam——alive。生物特徵比對——吻合。運送適格——cleared，但 restricted。日期——官方失蹤後第十一天。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）爸爸。在官方說他失蹤的十一天之後——有人替他做了體檢。有人記錄了他活著。有人簽了運送適格。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）這條鏈——不屬於原來那個國安管理部門。是——獨立的醫療轉送 clearance。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Lawyer, character: "律師", dialogue: "第二條。MAR-CONT maritime manifest／handoff receipt。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他打開第二個信封。另一張文件。格式不同。像是海上運送的簽收單。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "SUBJECT HASH——SAME。VEHICLE／VESSEL——RECORDED。HANDOFF——COMPLETED。DESTINATION CLASS——MAR-CONT／PROTECTIVE CUSTODY。RECEIVING RECEIPT——PRESENT。DISCHARGE RECORD——NONE FOUND／SEALED。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）同一個 hash。同一個人。車輛／船隻——有紀錄。交接——完成。目的地類別——MAR-CONT。保護性監管。接收方——有簽收。出院紀錄——沒有找到。或者——被封緘了。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）MAR-CONT。海上 continuity 路線。保護性轉送類別。不是——最終章新開的秘密海上基地。是——既有的程序分類。前章的 BCP 文件裡出現過。只是——那時候沒有人知道它被用來轉送過爸爸。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Lawyer, character: "律師", dialogue: "兩條鏈獨立交叉。同一個 subject hash。共同證明——官方失蹤後第十一日，你的父親仍然活著，並且完成了一次實際轉送。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Lawyer, character: "律師", dialogue: "不能成立的，我也必須告訴你。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著澪。語氣沒有變軟。也沒有變硬。像在讀一份清單。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Lawyer, character: "律師", dialogue: "目前是否仍活著——不能確認。是否已死亡——不能確認。是否一直被關到現在——不能確認。具體位置——不能確認。是否成為另一名受試者——不能確認。是否成為外星訊號接收者——不能確認。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Lawyer, character: "律師", dialogue: "DISCHARGE RECORD NONE FOUND 只代表後續資料仍封緘或缺失。不是——結論。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不能成立的——比能成立的多。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是——能成立的。能成立的——已經夠了。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）他在那一天之後還活過。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有說出聲。這句話在她的腦袋裡。很慢。像一塊石頭沉到水底。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）他被帶去了某個地方。後面仍然不知道。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著兩張文件。看著 subject hash。看著 STATUS AT EXAM——ALIVE。看著 HANDOFF——COMPLETED。看著 DISCHARGE RECORD——NONE FOUND／SEALED。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）第一次。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）第一次，不知道只是還不知道。不是制度替一個人寫好的死亡或離開。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把兩張文件放回信封。沒有哭。也沒有笑。只是——手指在信封邊緣停了很久。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）以前——不知道是什麼意思？以前——不知道是——官方已經寫好了答案。死亡。離家。失蹤。結案。不知道——是因為制度已經替你填好了那一欄。你只是——還沒收到。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）現在——不知道是什麼意思？現在——不知道是——真的不知道。後面——還有頁面。後面——還有封緘的東西。後面——可能永遠打不開。可是——不是因為有人已經替他寫好了結局。是——因為真的還沒走到。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "律師把兩個信封收進一個資料夾。推過來。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Lawyer, character: "律師", dialogue: "日下部先生已經失去警察權限。他不能再打開下一份檔案。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）日下部。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Lawyer, character: "律師", dialogue: "新頁面由家屬律師與法院交給你。不是——由警察交給你。也不是——由神鏡交給你。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）他不能了。他——交出了證件。他——被停職了。後來——正式失去了警察身分。他不能再以刑警的身分打開任何檔案。他不能再以制度的權限替我查爸爸的下落。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是——這兩條鏈。不是他查的。是——家屬律師。是——法院。是——獨立的醫療轉送紀錄和海上簽收單。是——制度自己留下的痕跡。不是——一個正義刑警偷偷帶出來的。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "窗外。下午的光已經偏了。百葉窗的影子變長。辦公室裡很安靜。冷氣在嗡。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）三個月。世界沒有變成一個乾淨的答案。可是——世界也沒有回到原來的謊言。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）爸爸。我在看了。不是——因為有人替我寫好了結局。是——因為第一次，不知道只是還不知道。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把資料夾收進背包。站起來。律師沒有多說。只點了一下頭。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走出辦公室。走廊很長。日光燈的白光打在地磚上。她的影子很清楚。", background: Background.Chapter_28_Ch28_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）後面仍然不知道。可是——不知道不再是——被寫好的那一頁。是——還沒翻到的下一頁。", background: Background.Chapter_28_Ch28_Act6_S0, portrait: Portrait.AsakuraMio_Base },
];
